"use strict";
(function ($) {
    "use strict";
    Gordic.Previews.register("buc:Prikaz", {
        // je možné náhled vykreslit?
        canRender: function (dto) {
            return (dto.ixp != null && dto.radek_uhr != null);
        },
        // vykreslení náhledu
        render: function (div, dto) {
            let currentElement = $(div);
            // titulek
            // TODO: dolatit podle detailu a šipek posunu po seznamu
            currentElement.empty().append("<h2 class='g-state-text g-state-active' style='margin: 0.5rem;'> " + "jres:33140091" + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/ > "); //RC 33140091 : Příkaz
            // PID zvlášť (je přes celou šířku)
            let form = $("<div class='gform--view-mode'>").appendTo(currentElement);
            form.gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" }).
                gformsection("create").gpidbar({ pid: dto.ixp });
            // a pak ostatní data
            let formBuilder = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1, breaks-300-400" })
                .addRow("Typ").addField("gstaticfield", { name: "upl_zkr" /* Gordic.Buc.Interface.GPrikazDtoNames.upl_zkr */ })
                //.addSection()
                .addRow("Stav").addField("gstaticfield", { name: "s_uhrp_zkr" /* Gordic.Buc.Interface.GPrikazDtoNames.s_uhrp_zkr */ })
                .addRow("Účet vlastní").addField("gstaticfield", { name: "bu_vl" /* Gordic.Buc.Interface.GPrikazDtoNames.bu_vl */ })
                .addRow("Sm.vl").addField("gstaticfield", { name: "sk_vl" })
                .addRow("Účet dodavatele").addField("gstaticfield", { name: "bu_ci" /* Gordic.Buc.Interface.GPrikazDtoNames.bu_ci */ })
                .addRow("Sm.dod").addField("gstaticfield", { name: "sk_ci" /* Gordic.Buc.Interface.GPrikazDtoNames.sk_ci */ })
                // TODO: přidat info o daňovém/nedaňovém pohybu (to dát i na seznam pohybů)
                .addRow("Částka").addField("gstaticfield", { name: "c" /* Gordic.Buc.Interface.GPrikazDtoNames.c */ })
                .addSection()
                .addRow("Měna").addField("gstaticfield", { name: "mena_txt" /* Gordic.Buc.Interface.GPrikazDtoNames.mena_txt */ })
                .addRow("Částka v měně").addField("gstaticfield", { name: "c_mena" /* Gordic.Buc.Interface.GPrikazDtoNames.c_mena */ })
                .addRow("Splatnost").addField("gstaticfield", { name: "dat_spl" /* Gordic.Buc.Interface.GPrikazDtoNames.dat_spl */, itemTemplate: "{#:date}" })
                .addRow("Splatnost ag.").addField("gstaticfield", { name: "dat_spl_ag" /* Gordic.Buc.Interface.GPrikazDtoNames.dat_spl_ag */, itemTemplate: "{#:date}" })
                .addRow("VS").addField("gstaticfield", { name: "vs" /* Gordic.Buc.Interface.GPrikazDtoNames.vs */ })
                .addRow("KS").addField("gstaticfield", { name: "ks" /* Gordic.Buc.Interface.GPrikazDtoNames.ks */ })
                .addRow("SS").addField("gstaticfield", { name: "ss" /* Gordic.Buc.Interface.GPrikazDtoNames.ss */ })
                .addRow("Způsob úhrady").addField("gstaticfield", { name: "zp_zkr" /* Gordic.Buc.Interface.GPrikazDtoNames.zp_zkr */ })
                .addRow("Agenda").addField("gstaticfield", { name: "zkr_ag" /* Gordic.Buc.Interface.GPrikazDtoNames.zkr_ag */ })
                .addRow("Agendové číslo").addField("gstaticfield", { name: "ac" /* Gordic.Buc.Interface.GPrikazDtoNames.ac */ })
                .addRow("Název").addField("gstaticfield", { name: "nazev" /* Gordic.Buc.Interface.GPrikazDtoNames.nazev */ })
                .addRow("IČO").addField("gstaticfield", { name: "ico_esu" /* Gordic.Buc.Interface.GPrikazDtoNames.ico_esu */ })
                .addRow("Identifikátor").addField("gstaticfield", { name: "ixp" /* Gordic.Buc.Interface.GPrikazDtoNames.ixp */ })
                .addRow("Popis").addField("gstaticfield", { name: "popis" /* Gordic.Buc.Interface.GPrikazDtoNames.popis */ })
                .addRow("DIČ").addField("gstaticfield", { name: "dic" /* Gordic.Buc.Interface.GPrikazDtoNames.dic */ })
                .addRow("Účtárna").addField("gstaticfield", { name: "uus" /* Gordic.Buc.Interface.GPrikazDtoNames.uus */ });
            // vytvoření formuláře a naplnění dat
            form.gform("createFrom", formBuilder).findFields().gfield("model", "apply", dto);
            currentElement.resize().find(".gform-section").children("label").first().addClass("g-state-text g-state-active");
        }
    });
    Gordic.Previews.register("buc:Davka", {
        // je možné náhled vykreslit?
        canRender: function (dto) {
            return (dto.ixp_dav != null /*&& dto.cislo_davky != null*/);
        },
        // vykreslení náhledu
        render: function (div, dto, fieldNames) {
            let currentElement = $(div);
            // titulek
            // TODO: dolatit podle detailu a šipek posunu po seznamu
            currentElement.empty().append("<h2 class='g-state-text g-state-active' style='margin: 0.5rem;'> " + dto.soubor + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/ > ");
            // PID zvlášť (je přes celou šířku)
            let form = $("<div class='gform--view-mode'>").appendTo(currentElement);
            form.gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" }).
                gformsection("create").gpidbar({ pid: dto.ixp_dav });
            // a pak ostatní data
            let formBuilder = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1, breaks-300-400" });
            form.gformsection("create")
                .gformrow("addFieldsRow", "Identifikátor").gformtext(dto.ixp_dav, "bold") //.addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.ixp_dav })
                .gformrow("addFieldsRow", "Číslo").gformtext(dto?.cislo_davky.toString(), "bold")
                .gformrow("addFieldsRow", "Označení dávky").gformtext(dto?.soubor, "bold")
                .gformrow("addFieldsRow", "Dat. vzniku").gformtext((dto.dat_vzn) ? new Date(dto.dat_vzn).toLocaleDateString() : "", "bold")
                .gformrow("addFieldsRow", "Dat. podpisu").gformtext((dto.dat_ppo) ? new Date(dto.dat_ppo).toLocaleDateString() : "", "bold")
                .gformrow("addFieldsRow", "Dat. odeslání").gformtext((dto.dat_ode) ? new Date(dto.dat_ode).toLocaleDateString() : "", "bold")
                .gformrow("addFieldsRow", "Poč. podpisů").gformtext(dto?.poc_pod.toString(), "bold")
                .gformrow("addFieldsRow", "Poznámka").gformtext(dto.poznamka, "bold")
                //.gformrow("addFieldsRow", "Banka").gformtext(dto.banka.toString(), "bold")
                .gformrow("addFieldsRow", "S").gformtext(dto.stav_zkr, "bold")
                .gformrow("addFieldsRow", "Stav dávky").gformtext(dto.s_dpb_txt, "bold")
                .gformrow("addFieldsRow", "SVD").gformtext(dto.s_vvu_zkr, "bold")
                .gformrow("addFieldsRow", "Počet p. ulož").gformtext(dto.poc_pod_ulo.toString(), "bold")
                .gformrow("addFieldsRow", "Počet příkazů").gformtext(dto.poc_pri.toString(), "bold")
                .gformrow("addFieldsRow", "Částka").gformtext(dto?.castka.toString(), "bold")
                .gformrow("addFieldsRow", "Vlastník").gformtext((dto.vlastnik) ? dto.vlastnik.toString() : "", "bold");
            // formBuilder
            //.addRow("Číslo").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.cislo_davky })
            //.addRow("Označení dávky").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.soubor })
            //.addRow("Dat. vzniku").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.dat_vzn, itemTemplate: "{#:date}" })
            //.addRow("Dat. podpisu").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.dat_ppo, itemTemplate: "{#:date}" })
            //.addRow("Dat. odeslání").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.dat_ode, itemTemplate: "{#:date}" })
            //.addRow("Poč. podpisů").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.poc_pod })
            //.addRow("poznámka").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.poznamka })
            //.addRow("Banka").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.banka })
            //.addRow("S").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.stav_zkr })
            //.addRow("Stav dávky").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.s_dpb_txt })
            //.addRow("SVD").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.s_vvu_zkr })
            //.addRow("Počet p. ulož.").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.poc_pod_ulo })
            //.addRow("Poč. příkazů").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.poc_pri })
            //.addRow("Částka").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.castka })
            //.addRow("Vlastník").addField("gstaticfield", { name: Gordic.Buc.Interface.GDavkaPDBDtoNames.vlastnik })
            // vytvoření formuláře a naplnění dat
            //form.gform("createFrom", formBuilder).findFields().gfield("model", "apply", dto);
            currentElement.resize().find(".gform-section").children("label").first().addClass("g-state-text g-state-active");
        }
    });
    //bankovní výpis
    Gordic.Previews.register("buc:BankovniVypisPreview", {
        canRender: (dto) => { return dto.ixp != null; },
        render: (div, dto) => {
            div.empty();
            var currentElement = $(div);
            //Gordic.Previews.displayLinkButton(div, dto);
            var form = $.newDiv("gform--view-mode").appendTo(currentElement)
                .gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" });
            form.gformsection("create").gpidbar({ pid: dto.ixp });
            form.gformsection("create").
                gformrow("addFieldsRow", "Agendové číslo").gformtext(dto.ac, "bold").
                gformrow("addFieldsRow", "Evidenční číslo").gformtext(dto.ac_ag, "bold").
                gformrow("addFieldsRow", "Stav").gformtext(dto.s_bvy_txt, "bold"). //RC 33500647 : Stav
                gformrow("addFieldsRow", "Datum nového zůstatku").gformtext((dto.dat_nov_zus) ? new Date(dto.dat_nov_zus).toLocaleDateString() : "", "bold").
                gformrow("addFieldsRow", "Datum starého zůstatku").gformtext((dto.dat_str_zus) ? new Date(dto.dat_str_zus).toLocaleDateString() : "", "bold").
                gformrow("addFieldsRow", "Obraty debet").gformtext(dto.obr_deb, "bold").
                gformrow("addFieldsRow", "Obraty kredit").gformtext(dto.obr_kre, "bold").
                gformrow("addFieldsRow", "Starý zůstatek").gformtext(dto.str_zus, "bold").
                gformrow("addFieldsRow", "Nový zůstatek").gformtext(dto.nov_zus, "bold").
                gformrow("addFieldsRow", "Typ").gformtext(dto.typ_vypis_txt, "bold").
                gformrow("addFieldsRow", "Bilanční převod").gformtext(dto.c_bil, "bold").
                gformrow("addFieldsRow", "Limit debetního zůstatku").gformtext(dto.c_limdz, "bold").
                gformrow("addFieldsRow", "Rezervace").gformtext(dto.c_rez, "bold");
            //currentElement.resize().find(".gform-section").children("label").first().addClass("g-state-text g-state-error");
        },
    });
})(jQuery);
